pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // sep is guaranteed non-empty by the problem statement.
    let k = maxsplit as usize;

    a.into_iter()
        .map(|s| {
            if k == 0 {
                return vec![s];
            }

            let mut parts: Vec<String> = Vec::new();
            let mut remaining: &str = &s;

            for _ in 0..k {
                if let Some(pos) = remaining.rfind(&sep) {
                    let after = &remaining[pos + sep.len()..];
                    parts.push(after.to_string());
                    remaining = &remaining[..pos];
                } else {
                    break;
                }
            }

            parts.push(remaining.to_string());
            parts.reverse();
            parts
        })
        .collect()
}